49	namespace tfprof {
50	void completion(const char* buf, linenoiseCompletions* lc) {
51	  std::string buf_str = buf;
52	  if (buf_str.find(' ') == buf_str.npos) {
53	    for (const char* opt : kCmds) {
54	      if (absl::StartsWith(opt, buf_str)) {
55	        linenoiseAddCompletion(lc, opt);
56	      }
57	    }
58	    return;
59	  }
60	
61	  std::string prefix;
62	  int last_dash = buf_str.find_last_of(' ');
63	  if (last_dash != std::string::npos) {
64	    prefix = buf_str.substr(0, last_dash + 1);
65	    buf_str =
66	        buf_str.substr(last_dash + 1, std::numeric_limits<int32_t>::max());
67	  }
68	  for (const char* opt : kOptions) {
69	    if (absl::StartsWith(opt, buf_str)) {
70	      linenoiseAddCompletion(lc, (prefix + opt).c_str());
71	    }
72	  }
73	}
74	
75	int Run(int argc, char** argv) {
76	  std::string FLAGS_profile_path = "";
77	  std::string FLAGS_graph_path = "";
78	  std::string FLAGS_run_meta_path = "";
79	  std::string FLAGS_op_log_path = "";
80	  std::string FLAGS_checkpoint_path = "";
81	  int32_t FLAGS_max_depth = 10;
82	  int64_t FLAGS_min_bytes = 0;
83	  int64_t FLAGS_min_peak_bytes = 0;
84	  int64_t FLAGS_min_residual_bytes = 0;
85	  int64_t FLAGS_min_output_bytes = 0;
86	  int64_t FLAGS_min_micros = 0;
87	  int64_t FLAGS_min_accelerator_micros = 0;
88	  int64_t FLAGS_min_cpu_micros = 0;
89	  int64_t FLAGS_min_params = 0;
90	  int64_t FLAGS_min_float_ops = 0;
91	  int64_t FLAGS_min_occurrence = 0;
92	  int64_t FLAGS_step = -1;
93	  std::string FLAGS_order_by = "name";
94	  std::string FLAGS_account_type_regexes = ".*";
95	  std::string FLAGS_start_name_regexes = ".*";
96	  std::string FLAGS_trim_name_regexes = "";
97	  std::string FLAGS_show_name_regexes = ".*";
98	  std::string FLAGS_hide_name_regexes;
99	  bool FLAGS_account_displayed_op_only = false;
100	  std::string FLAGS_select = "micros";
101	  std::string FLAGS_output = "";
102	  for (int i = 0; i < argc; i++) {
103	    absl::FPrintF(stderr, "%s\n", argv[i]);
104	  }
105	
106	  std::vector<Flag> flag_list = {
107	      Flag("profile_path", &FLAGS_profile_path, "Profile binary file name"),
108	      Flag("graph_path", &FLAGS_graph_path, "GraphDef proto text file name"),
109	      Flag("run_meta_path", &FLAGS_run_meta_path,
110	           "Comma-separated list of RunMetadata proto binary "
111	           "files. Each file is given step number 0,1,2,etc"),
112	      Flag("op_log_path", &FLAGS_op_log_path,
113	           "tensorflow::tfprof::OpLogProto proto binary file name"),
114	      Flag("checkpoint_path", &FLAGS_checkpoint_path,
115	           "TensorFlow Checkpoint file name"),
116	      Flag("max_depth", &FLAGS_max_depth, "max depth"),
117	      Flag("min_bytes", &FLAGS_min_bytes, "min_bytes"),
118	      Flag("min_peak_bytes", &FLAGS_min_peak_bytes, "min_peak_bytes"),
119	      Flag("min_residual_bytes", &FLAGS_min_residual_bytes,
120	           "min_residual_bytes"),
121	      Flag("min_output_bytes", &FLAGS_min_output_bytes, "min_output_bytes"),
122	      Flag("min_micros", &FLAGS_min_micros, "min micros"),
123	      Flag("min_accelerator_micros", &FLAGS_min_accelerator_micros,
124	           "min accelerator_micros"),
125	      Flag("min_cpu_micros", &FLAGS_min_cpu_micros, "min_cpu_micros"),
126	      Flag("min_params", &FLAGS_min_params, "min params"),
127	      Flag("min_float_ops", &FLAGS_min_float_ops, "min float ops"),
128	      Flag("min_occurrence", &FLAGS_min_occurrence, "min occurrence"),
129	      Flag("step", &FLAGS_step,
130	           "The stats of which step to use. By default average"),
131	      Flag("order_by", &FLAGS_order_by, "order by"),
132	      Flag("account_type_regexes", &FLAGS_start_name_regexes,
133	           "start name regexes"),
134	      Flag("trim_name_regexes", &FLAGS_trim_name_regexes, "trim name regexes"),
135	      Flag("show_name_regexes", &FLAGS_show_name_regexes, "show name regexes"),
136	      Flag("hide_name_regexes", &FLAGS_hide_name_regexes, "hide name regexes"),
137	      Flag("account_displayed_op_only", &FLAGS_account_displayed_op_only,
138	           "account displayed op only"),
139	      Flag("select", &FLAGS_select, "select"),
140	      Flag("output", &FLAGS_output, "output"),
141	  };
142	  std::string usage = Flags::Usage(argv[0], flag_list);
143	  bool parse_ok = Flags::Parse(&argc, argv, flag_list);
144	  if (!parse_ok) {
145	    absl::PrintF("%s", usage);
146	    return (2);
147	  }
148	  port::InitMain(argv[0], &argc, &argv);
149	
150	  if (!FLAGS_profile_path.empty() &&
151	      (!FLAGS_graph_path.empty() || !FLAGS_run_meta_path.empty())) {
152	    absl::FPrintF(stderr,
153	                  "--profile_path is set, do not set --graph_path or "
154	                  "--run_meta_path\n");
155	    return 1;
156	  }
157	
158	  std::vector<std::string> account_type_regexes =
159	      absl::StrSplit(FLAGS_account_type_regexes, ',', absl::SkipEmpty());
160	  std::vector<std::string> start_name_regexes =
161	      absl::StrSplit(FLAGS_start_name_regexes, ',', absl::SkipEmpty());
162	  std::vector<std::string> trim_name_regexes =
163	      absl::StrSplit(FLAGS_trim_name_regexes, ',', absl::SkipEmpty());
164	  std::vector<std::string> show_name_regexes =
165	      absl::StrSplit(FLAGS_show_name_regexes, ',', absl::SkipEmpty());
166	  std::vector<std::string> hide_name_regexes =
167	      absl::StrSplit(FLAGS_hide_name_regexes, ',', absl::SkipEmpty());
168	  std::vector<std::string> select =
169	      absl::StrSplit(FLAGS_select, ',', absl::SkipEmpty());
170	
171	  std::string output_type;
172	  std::map<std::string, std::string> output_options;
173	  absl::Status s = ParseOutput(FLAGS_output, &output_type, &output_options);
174	  CHECK(s.ok()) << s;
175	
176	  std::string cmd = "";
177	  if (argc == 1 && FLAGS_graph_path.empty() && FLAGS_profile_path.empty() &&
178	      FLAGS_run_meta_path.empty()) {
179	    PrintHelp();
180	    return 0;
181	  } else if (argc > 1) {
182	    if (std::string(argv[1]) == kCmds[6]) {
183	      PrintHelp();
184	      return 0;
185	    }
186	    if (std::string(argv[1]) == kCmds[0] || std::string(argv[1]) == kCmds[1] ||
187	        std::string(argv[1]) == kCmds[2] || std::string(argv[1]) == kCmds[3] ||
188	        std::string(argv[1]) == kCmds[4]) {
189	      cmd = argv[1];
190	    }
191	  }
192	
193	  absl::PrintF("Reading Files...\n");
194	  std::unique_ptr<checkpoint::CheckpointReader> ckpt_reader;
195	  TF_Status* status = TF_NewStatus();
196	  if (!FLAGS_checkpoint_path.empty()) {
197	    ckpt_reader = std::make_unique<checkpoint::CheckpointReader>(
198	        FLAGS_checkpoint_path, status);
199	    if (TF_GetCode(status) != TF_OK) {
200	      absl::FPrintF(stderr, "%s\n", TF_Message(status));
201	      TF_DeleteStatus(status);
202	      return 1;
203	    }
204	    TF_DeleteStatus(status);
205	  }
206	
207	  std::unique_ptr<TFStats> tf_stat;
208	  if (!FLAGS_profile_path.empty()) {
209	    tf_stat =
210	        std::make_unique<TFStats>(FLAGS_profile_path, std::move(ckpt_reader));
211	  } else {
212	    absl::PrintF(
213	        "Try to use a single --profile_path instead of "
214	        "graph_path,op_log_path,run_meta_path\n");
215	    std::unique_ptr<GraphDef> graph = std::make_unique<GraphDef>();
216	    if (!FLAGS_graph_path.empty()) {
217	      s = ReadProtoFile(Env::Default(), FLAGS_graph_path, graph.get(), false);
218	      if (!s.ok()) {
219	        absl::FPrintF(stderr, "Failed to read graph_path: %s\n", s.ToString());
220	        return 1;
221	      }
222	    }
223	
224	    std::unique_ptr<OpLogProto> op_log = std::make_unique<OpLogProto>();
225	    if (!FLAGS_op_log_path.empty()) {
226	      std::string op_log_str;
227	      s = ReadFileToString(Env::Default(), FLAGS_op_log_path, &op_log_str);
228	      if (!s.ok()) {
229	        absl::FPrintF(stderr, "Failed to read op_log_path: %s\n", s.ToString());
230	        return 1;
231	      }
232	      if (!ParseProtoUnlimited(op_log.get(), op_log_str)) {
233	        absl::FPrintF(stderr, "Failed to parse op_log_path\n");
234	        return 1;
235	      }
236	    }
237	    tf_stat = std::make_unique<TFStats>(
238	        std::move(graph), nullptr, std::move(op_log), std::move(ckpt_reader));
239	
240	    std::vector<std::string> run_meta_files =
241	        absl::StrSplit(FLAGS_run_meta_path, ',', absl::SkipEmpty());
242	    for (int i = 0; i < run_meta_files.size(); ++i) {
243	      std::unique_ptr<RunMetadata> run_meta = std::make_unique<RunMetadata>();
244	      s = ReadProtoFile(Env::Default(), run_meta_files[i], run_meta.get(),
245	                        true);
246	      if (!s.ok()) {
247	        absl::FPrintF(stderr, "Failed to read run_meta_path %s. Status: %s\n",
248	                      run_meta_files[i], s.ToString());
249	        return 1;
250	      }
251	      tf_stat->AddRunMeta(i, std::move(run_meta));
252	      absl::FPrintF(stdout, "run graph coverage: %.2f\n",
253	                    tf_stat->run_coverage());
254	    }
255	  }
256	
257	  if (cmd == kCmds[4]) {
258	    tf_stat->BuildAllViews();
259	    Advisor(tf_stat.get()).Advise(Advisor::DefaultOptions());
260	    return 0;
261	  }
262	
263	  Options opts(
264	      FLAGS_max_depth, FLAGS_min_bytes, FLAGS_min_peak_bytes,
265	      FLAGS_min_residual_bytes, FLAGS_min_output_bytes, FLAGS_min_micros,
266	      FLAGS_min_accelerator_micros, FLAGS_min_cpu_micros, FLAGS_min_params,
267	      FLAGS_min_float_ops, FLAGS_min_occurrence, FLAGS_step, FLAGS_order_by,
268	      account_type_regexes, start_name_regexes, trim_name_regexes,
269	      show_name_regexes, hide_name_regexes, FLAGS_account_displayed_op_only,
270	      select, output_type, output_options);
271	
272	  if (cmd == kCmds[2] || cmd == kCmds[3]) {
273	    tf_stat->BuildView(cmd);
274	    tf_stat->ShowMultiGraphNode(cmd, opts);
275	    return 0;
276	  } else if (cmd == kCmds[0] || cmd == kCmds[1]) {
277	    tf_stat->BuildView(cmd);
278	    tf_stat->ShowGraphNode(cmd, opts);
279	    return 0;
280	  }
281	
282	  linenoiseSetCompletionCallback(completion);
283	  linenoiseHistoryLoad(".tfprof_history.txt");
284	
285	  bool looped = false;
286	  while (true) {
287	    char* line = linenoise("tfprof> ");
288	    if (line == nullptr) {
289	      if (!looped) {
290	        absl::FPrintF(stderr,
291	                      "Cannot start interactive shell, "
292	                      "use 'bazel-bin' instead of 'bazel run'.\n");
293	      }
294	      break;
295	    }
296	    looped = true;
297	    std::string line_s = line;
298	    free(line);
299	
300	    if (line_s.empty()) {
301	      absl::PrintF("%s", opts.ToString());
302	      continue;
303	    }
304	    linenoiseHistoryAdd(line_s.c_str());
305	    linenoiseHistorySave(".tfprof_history.txt");
306	
307	    Options new_opts = opts;
308	    absl::Status s = ParseCmdLine(line_s, &cmd, &new_opts);
309	    if (!s.ok()) {
310	      absl::FPrintF(stderr, "E: %s\n", s.ToString());
311	      continue;
312	    }
313	    if (cmd == kCmds[5]) {
314	      opts = new_opts;
315	    } else if (cmd == kCmds[6]) {
316	      PrintHelp();
317	    } else if (cmd == kCmds[2] || cmd == kCmds[3]) {
318	      tf_stat->BuildView(cmd);
319	      tf_stat->ShowMultiGraphNode(cmd, new_opts);
320	    } else if (cmd == kCmds[0] || cmd == kCmds[1]) {
321	      tf_stat->BuildView(cmd);
322	      tf_stat->ShowGraphNode(cmd, new_opts);
323	    } else if (cmd == kCmds[4]) {
324	      tf_stat->BuildAllViews();
325	      Advisor(tf_stat.get()).Advise(Advisor::DefaultOptions());
326	    }
327	  }
328	  return 0;
329	}
330	}  // namespace tfprof
331	}  // namespace tensorflow
332	
333	int main(int argc, char** argv) { return tensorflow::tfprof::Run(argc, argv); }
334

