37	
38	namespace tsl {
39	namespace profiler {
40	
41	constexpr uint64_t kTraceMeDefaultFilterMask =
42	    std::numeric_limits<uint64_t>::max();
43	
44	// Predefined levels:
45	// - Level 1 (kCritical) is the default and used only for user instrumentation.
46	// - Level 2 (kInfo) is used by profiler for instrumenting high level program
47	//   execution details (expensive TF ops, XLA ops, etc).
48	// - Level 3 (kVerbose) is also used by profiler to instrument more verbose
49	//   (low-level) program execution details (cheap TF ops, etc).
50	enum TraceMeLevel {
51	  kCritical = 1,
52	  kInfo = 2,
53	  kVerbose = 3,
54	};
55	
56	// This is specifically used for instrumenting Tensorflow ops.
57	// Takes input as whether a TF op is expensive or not and returns the TraceMe
58	// level to be assigned to trace that particular op. Assigns level 2 for
59	// expensive ops (these are high-level details and shown by default in profiler
60	// UI). Assigns level 3 for cheap ops (low-level details not shown by default).
61	inline int GetTFTraceMeLevel(bool is_expensive) {
62	  return is_expensive ? kInfo : kVerbose;
63	}
64	
65	// This class permits user-specified (CPU) tracing activities. A trace activity
66	// is started when an object of this class is created and stopped when the
67	// object is destroyed.
68	//
69	// CPU tracing can be useful when trying to understand what parts of GPU
70	// computation (e.g., kernels and memcpy) correspond to higher level activities
71	// in the overall program. For instance, a collection of kernels maybe
72	// performing one "step" of a program that is better visualized together than
73	// interspersed with kernels from other "steps". Therefore, a TraceMe object
74	// can be created at each "step".
75	//
76	// Two APIs are provided:
77	//   (1) Scoped object: a TraceMe object starts tracing on construction, and
78	//       stops tracing when it goes out of scope.
79	//          {
80	//            TraceMe trace("step");
81	//            ... do some work ...
82	//          }
83	//       TraceMe objects can be members of a class, or allocated on the heap.
84	//   (2) Static methods: ActivityStart and ActivityEnd may be called in pairs.
85	//          auto id = ActivityStart("step");
86	//          ... do some work ...
87	//          ActivityEnd(id);
88	//       The two static methods should be called within the same thread.
89	class TraceMe {
90	 public:
91	  // Constructor that traces a user-defined activity labeled with name
92	  // in the UI. Level defines the trace priority, used for filtering TraceMe
93	  // events. By default, traces with TraceMe level <= 2 are recorded. Levels:
94	  // - Must be a positive integer.
95	  // - Can be a value in enum TraceMeLevel.
96	  // Users are welcome to use level > 3 in their code, if they wish to filter
97	  // out their host traces based on verbosity.
98	  explicit TraceMe(absl::string_view name, int level = 1,
99	                   uint64_t filter_mask = kTraceMeDefaultFilterMask) {
100	    DCHECK_GE(level, 1);
101	#if !defined(IS_MOBILE_PLATFORM)
102	    if (TF_PREDICT_FALSE(TraceMeRecorder::Active(level) &&
103	                         TraceMeRecorder::CheckFilter(filter_mask))) {
104	      name_.Emplace(std::string(name));
105	      start_time_ = GetCurrentTimeNanos();
106	    }
107	#endif
108	  }
109	
110	  // Do not allow passing a temporary string as the overhead of generating that
111	  // string should only be incurred when tracing is enabled. Wrap the temporary
112	  // string generation (e.g., StrCat) in a lambda and use the name_generator
113	  // template instead.
114	  explicit TraceMe(std::string&& name, int level = 1,
115	                   uint64_t filter_mask = kTraceMeDefaultFilterMask) = delete;
116	
117	  // Do not allow passing strings by reference or value since the caller
118	  // may unintentionally maintain ownership of the name.
119	  // Explicitly wrap the name in a string_view if you really wish to maintain
120	  // ownership of a string already generated for other purposes. For temporary
121	  // strings (e.g., result of StrCat) use the name_generator template.
122	  explicit TraceMe(const std::string& name, int level = 1,
123	                   uint64_t filter_mask = kTraceMeDefaultFilterMask) = delete;
124	
125	  // This overload is necessary to make TraceMe's with string literals work.
126	  // Otherwise, the name_generator template would be used.
127	  explicit TraceMe(const char* raw, int level = 1,
128	                   uint64_t filter_mask = kTraceMeDefaultFilterMask)
129	      : TraceMe(absl::string_view(raw), level, filter_mask) {}
130	
131	  // This overload only generates the name (and possibly metadata) if tracing is
132	  // enabled. Useful for avoiding expensive operations (e.g., string
133	  // concatenation) when tracing is disabled.
134	  // name_generator may be a lambda or functor that returns a type that the
135	  // string() constructor can take, e.g., the result of TraceMeEncode.
136	  // name_generator is templated, rather than a std::function to avoid
137	  // allocations std::function might make even if never called.
138	  // Example Usage:
139	  //   TraceMe trace_me([&]() {
140	  //     return StrCat("my_trace", id);
141	  //   }
142	  //   TraceMe op_trace_me([&]() {
143	  //     return TraceMeOp(op_name, op_type);
144	  //   }
145	  //   TraceMe trace_me_with_metadata([&value1]() {
146	  //     return TraceMeEncode("my_trace", {{"key1", value1}, {"key2", 42}});
147	  //   });
148	  template <typename NameGeneratorT,
149	            std::enable_if_t<std::is_invocable_v<NameGeneratorT>, bool> = true>
150	  explicit TraceMe(NameGeneratorT&& name_generator, int level = 1,
151	                   uint64_t filter_mask = kTraceMeDefaultFilterMask) {
152	    DCHECK_GE(level, 1);
153	#if !defined(IS_MOBILE_PLATFORM)
154	    if (TF_PREDICT_FALSE(TraceMeRecorder::Active(level) &&
155	                         TraceMeRecorder::CheckFilter(filter_mask))) {
156	      name_.Emplace(std::forward<NameGeneratorT>(name_generator)());
157	      start_time_ = GetCurrentTimeNanos();
158	    } else {
159	#ifndef NDEBUG
160	      // Always invoke the name generator on debug builds to catch bugs in name
161	      // generators that would otherwise only be caught when tracing is enabled.
162	      std::forward<NameGeneratorT>(name_generator)();
163	#endif
164	    }
165	#endif
166	  }
167	
168	  // Movable.
169	  TraceMe(TraceMe&& other) noexcept { *this = std::move(other); }
170	  TraceMe& operator=(TraceMe&& other) noexcept {
171	#if !defined(IS_MOBILE_PLATFORM)
172	    if (TF_PREDICT_FALSE(other.start_time_ != kUntracedActivity)) {
173	      name_.Emplace(std::move(other.name_).Consume());
174	      start_time_ = std::exchange(other.start_time_, kUntracedActivity);
175	    }
176	#endif
177	    return *this;
178	  }
179	
180	  ~TraceMe() { Stop(); }
181	
182	  // Stop tracing the activity. Called by the destructor, but exposed to allow
183	  // stopping tracing before the object goes out of scope. Only has an effect
184	  // the first time it is called.
185	  void Stop() {
186	    // We do not need to check the trace level again here.
187	    // - If tracing wasn't active to start with, we have kUntracedActivity.
188	    // - If tracing was active and was stopped, we have
189	    //   TraceMeRecorder::Active().
190	    // - If tracing was active and was restarted at a lower level, we may
191	    //   spuriously record the event. This is extremely rare, and acceptable as
192	    //   event will be discarded when its start timestamp fall outside of the
193	    //   start/stop session timestamp.
194	#if !defined(IS_MOBILE_PLATFORM)
195	    if (TF_PREDICT_FALSE(start_time_ != kUntracedActivity)) {
196	      if (TF_PREDICT_TRUE(TraceMeRecorder::Active())) {
197	        TraceMeRecorder::Record(
198	            {std::move(name_.value), start_time_, GetCurrentTimeNanos()});
199	      }
200	      name_.Destroy();
201	      start_time_ = kUntracedActivity;
202	    }
203	#endif
204	  }
205	
206	  // Appends new_metadata to the TraceMe name passed to the constructor.
207	  // metadata_generator may be a lambda or functor that returns a type that the
208	  // string() constructor can take, e.g., the result of TraceMeEncode.
209	  // metadata_generator is only evaluated when tracing is enabled.
210	  // metadata_generator is templated, rather than a std::function to avoid
211	  // allocations std::function might make even if never called.
212	  // Example Usage:
213	  //   trace_me.AppendMetadata([&value1]() {
214	  //     return TraceMeEncode({{"key1", value1}, {"key2", 42}});
215	  //   });
216	  template <
217	      typename MetadataGeneratorT,
218	      std::enable_if_t<std::is_invocable_v<MetadataGeneratorT>, bool> = true>
219	  void AppendMetadata(MetadataGeneratorT&& metadata_generator) {
220	#if !defined(IS_MOBILE_PLATFORM)
221	    if (TF_PREDICT_FALSE(start_time_ != kUntracedActivity) &&
222	        TF_PREDICT_TRUE(TraceMeRecorder::Active())) {
223	      traceme_internal::AppendMetadata(
224	          &name_.value, std::forward<MetadataGeneratorT>(metadata_generator)());
225	    } else {
226	#ifndef NDEBUG
227	      // Always invoke the name generator on debug builds to catch bugs in name
228	      // generators that would otherwise only be caught when tracing is enabled.
229	      std::forward<MetadataGeneratorT>(metadata_generator)();
230	#endif
231	    }
232	#endif
233	  }
234	
235	  // Static API, for use when scoped objects are inconvenient.
236	
237	  // Record the start time of an activity.
238	  // Returns the activity ID, which is used to stop the activity.
239	  // Calls `name_generator` to get the name for activity.
240	  template <typename NameGeneratorT,
241	            std::enable_if_t<std::is_invocable_v<NameGeneratorT>, bool> = true>
242	  static int64_t ActivityStart(
243	      NameGeneratorT&& name_generator, int level = 1,
244	      uint64_t filter_mask = kTraceMeDefaultFilterMask) {
245	#if !defined(IS_MOBILE_PLATFORM)
246	    if (TF_PREDICT_FALSE(TraceMeRecorder::Active(level) &&
247	                         TraceMeRecorder::CheckFilter(filter_mask))) {
248	      int64_t activity_id = TraceMeRecorder::NewActivityId();
249	      TraceMeRecorder::Record({std::forward<NameGeneratorT>(name_generator)(),
250	                               GetCurrentTimeNanos(), -activity_id});
251	      return activity_id;
252	    } else {
253	#ifndef NDEBUG
254	      // Always invoke the name generator on debug builds to catch bugs in name
255	      // generators that would otherwise only be caught when tracing is enabled.
256	      std::forward<NameGeneratorT>(name_generator)();
257	#endif
258	    }
259	#endif
260	    return kUntracedActivity;
261	  }
262	
263	  // Record the start time of an activity.
264	  // Returns the activity ID, which is used to stop the activity.
265	  static int64_t ActivityStart(
266	      absl::string_view name, int level = 1,
267	      uint64_t filter_mask = kTraceMeDefaultFilterMask) {
268	#if !defined(IS_MOBILE_PLATFORM)
269	    if (TF_PREDICT_FALSE(TraceMeRecorder::Active(level) &&
270	                         TraceMeRecorder::CheckFilter(filter_mask))) {
271	      int64_t activity_id = TraceMeRecorder::NewActivityId();
272	      TraceMeRecorder::Record(
273	          {std::string(name), GetCurrentTimeNanos(), -activity_id});
274	      return activity_id;
275	    }
276	#endif
277	    return kUntracedActivity;
278	  }
279	
280	  // Same as ActivityStart above, an overload for "const std::string&"
281	  static int64_t ActivityStart(
282	      const std::string& name, int level = 1,
283	      uint64_t filter_mask = kTraceMeDefaultFilterMask) {
284	    return ActivityStart(absl::string_view(name), level, filter_mask);
285	  }
286	
287	  // Same as ActivityStart above, an overload for "const char*"
288	  static int64_t ActivityStart(
289	      const char* name, int level = 1,
290	      uint64_t filter_mask = kTraceMeDefaultFilterMask) {
291	    return ActivityStart(absl::string_view(name), level, filter_mask);
292	  }
293	
294	  // Record the end time of an activity started by ActivityStart().
295	  static void ActivityEnd(int64_t activity_id) {
296	#if !defined(IS_MOBILE_PLATFORM)
297	    // We don't check the level again (see TraceMe::Stop()).
298	    if (TF_PREDICT_FALSE(activity_id != kUntracedActivity)) {
299	      if (TF_PREDICT_TRUE(TraceMeRecorder::Active())) {
300	        TraceMeRecorder::Record(
301	            {std::string(), -activity_id, GetCurrentTimeNanos()});
302	      }
303	    }
304	#endif
305	  }
306	
307	  // Records the time of an instant activity.
308	  template <typename NameGeneratorT,
309	            std::enable_if_t<std::is_invocable_v<NameGeneratorT>, bool> = true>
310	  static void InstantActivity(
311	      NameGeneratorT&& name_generator, int level = 1,
312	      uint64_t filter_mask = kTraceMeDefaultFilterMask) {
313	#if !defined(IS_MOBILE_PLATFORM)
314	    if (TF_PREDICT_FALSE(TraceMeRecorder::Active(level) &&
315	                         TraceMeRecorder::CheckFilter(filter_mask))) {
316	      int64_t now = GetCurrentTimeNanos();
317	      TraceMeRecorder::Record({std::forward<NameGeneratorT>(name_generator)(),
318	                               /*start_time=*/now, /*end_time=*/now});
319	    } else {
320	#ifndef NDEBUG
321	      // Always invoke the name generator on debug builds to catch bugs in name
322	      // generators that would otherwise only be caught when tracing is enabled.
323	      std::forward<NameGeneratorT>(name_generator)();
324	#endif
325	    }
326	#endif
327	  }
328	
329	  static bool Active(int level = 1) {
330	#if !defined(IS_MOBILE_PLATFORM)
331	    return TraceMeRecorder::Active(level);
332	#else
333	    return false;
334	#endif
335	  }
336	
337	  static int64_t NewActivityId() {
338	#if !defined(IS_MOBILE_PLATFORM)
339	    return TraceMeRecorder::NewActivityId();
340	#else
341	    return 0;
342	#endif
343	  }
344	
345	 private:
346	  // Start time used when tracing is disabled.
347	  constexpr static int64_t kUntracedActivity = 0;
348	
349	  TraceMe(const TraceMe&) = delete;
350	  void operator=(const TraceMe&) = delete;
351	
352	  NoInit<std::string> name_;
353	
354	  int64_t start_time_ = kUntracedActivity;
355	};
356	
357	// Whether OpKernel::TraceString will populate additional information for
358	// profiler, such as tensor shapes.
359	inline bool TfOpDetailsEnabled() {
360	  return TraceMe::Active(TraceMeLevel::kVerbose);
361	}
362	
363	}  // namespace profiler
364	}  // namespace tsl
365	
366	#endif  // TENSORFLOW_TSL_PROFILER_LIB_TRACEME_H_
