32	
33	namespace tsl {
34	
35	// A profiler which will start profiling when creating the object and will stop
36	// when either the object is destroyed or CollectData is called.
37	// Multiple instances can be created, but at most one of them will profile.
38	// Status() will return OK only for the instance that is profiling.
39	// Thread-safety: ProfilerSession is thread-safe.
40	class ProfilerSession {
41	 public:
42	  // Creates a ProfilerSession and starts profiling.
43	  static std::unique_ptr<ProfilerSession> Create(
44	      const tensorflow::ProfileOptions& options);
45	
46	  static tensorflow::ProfileOptions DefaultOptions() {
47	    tensorflow::ProfileOptions options;
48	    options.set_version(1);
49	    options.set_device_tracer_level(1);
50	    options.set_host_tracer_level(2);
51	    options.set_device_type(tensorflow::ProfileOptions::UNSPECIFIED);
52	    options.set_python_tracer_level(0);
53	    options.set_enable_hlo_proto(true);
54	    options.set_include_dataset_ops(true);
55	    return options;
56	  }
57	
58	  // Deletes an existing Profiler and enables starting a new one.
59	  ~ProfilerSession();
60	
61	  absl::Status Status() TF_LOCKS_EXCLUDED(mutex_);
62	
63	  // Collects profile data into XSpace.
64	  absl::Status CollectData(tensorflow::profiler::XSpace* space)
65	      TF_LOCKS_EXCLUDED(mutex_);
66	
67	  absl::Status Stop() TF_LOCKS_EXCLUDED(mutex_);
68	
69	  std::vector<tensorflow::profiler::XSpace> SerializeChunks()
70	      TF_LOCKS_EXCLUDED(mutex_);
71	
72	  bool IsContinuousProfilingEnabled() const;
73	
74	 private:
75	  // Constructs an instance of the class and starts profiling
76	  explicit ProfilerSession(const tensorflow::ProfileOptions& options);
77	
78	  // ProfilerSession is neither copyable or movable.
79	  ProfilerSession(const ProfilerSession&) = delete;
80	  ProfilerSession& operator=(const ProfilerSession&) = delete;
81	
82	#if !defined(IS_MOBILE_PLATFORM)
83	  // Collects profile data into XSpace without post-processsing.
84	  absl::Status CollectDataInternal(tensorflow::profiler::XSpace* space);
85	
86	  profiler::ProfilerLock profiler_lock_ TF_GUARDED_BY(mutex_);
87	
88	  std::unique_ptr<profiler::ProfilerInterface> profilers_ TF_GUARDED_BY(mutex_);
89	
90	  uint64_t start_time_ns_;
91	  uint64_t stop_time_ns_;
92	  tensorflow::ProfileOptions options_;
93	#endif
94	  absl::Status status_ TF_GUARDED_BY(mutex_);
95	  absl::Mutex mutex_;
96	};
97	
98	}  // namespace tsl
99	#endif  // TENSORFLOW_TSL_PROFILER_LIB_PROFILER_SESSION_H_
